 const guard=async(work:()=>Promise<any>)=>{setBusy(true);try{return await work()}catch(e){notify((e as Error).message);if((e as any).status===409&&current.current&&(!projectAction||projectAction.project?.id===current.current.id)){try{setConflictRemote(await api('/projects/'+current.current.id))}catch{}}return null}finally{setBusy(false)}};
