 const edit=(fn:(p:Project)=>void)=>{if(!project)return;const p=structuredClone(project);fn(p);invalidateScriptTask(p,project);if(['story','parameters','duration','script_mode','story_policy','script_workflow','video_brief'].some(k=>JSON.stringify(p[k])!==JSON.stringify(project[k]))){p.script_needs_rewrite=true;p.script_confirmed=false;p.native_storyboard_current=false;p.confirmed=false;for(const k of ['video_spec','video_spec_markdown','script_workflow','script_workflow_plan'])delete p.documents[k];delete p.documents.script_consistency;}if(p.documents.script!==project.documents.script){p.script_needs_rewrite=false;p.script_confirmed=false;delete p.documents.script_workflow_plan;delete p.documents.script_consistency;p.assets.forEach(a=>{if(a.visual_profile)a.profile_stale=true});}if(p.storyboard_generation&&(['parameters','duration','production_scheme','storyboard_notes'].some(k=>JSON.stringify(p[k])!==JSON.stringify(project[k]))||p.documents.script!==project.documents.script||JSON.stringify(p.assets.map(a=>Object.fromEntries(['id','kind','name','description','personality','age','gender','costume','visual_profile'].map(k=>[k,a[k]]))))!==JSON.stringify(project.assets.map(a=>Object.fromEntries(['id','kind','name','description','personality','age','gender','costume','visual_profile'].map(k=>[k,a[k]])))))){p.storyboard_generation.status='stale';p.storyboard_generation.message=p.storyboard_notes!==project.storyboard_notes?'汇总修订要求已修改；请保存后重新生成汇总，旧镜头保留。':'剧本、方案或元素外观已修改；请保存后重新生成分镜汇总。';}if(p.timing_revision&&(p.storyboard_generation?.status==='stale'||JSON.stringify(p.shots.map(s=>[s.id,s.duration,s.prompt,s.actions]))!==JSON.stringify(project.shots.map(s=>[s.id,s.duration,s.prompt,s.actions])))){p.timing_revision.status='stale';p.timing_revision.message='分镜或生成依据已修改；请重新修正时间标签。';}projectHistory.current.record(project,p);setHistoryVersion(v=>v+1);current.current=p;dirtyRef.current=true;setProject(p);setDirty(true);};
