 const job=async(kind:string,target?:string,options?:Obj)=>guard(async()=>{let p=await save();const opts={...options};const outlineReview={revision:p.revision,semantic_review:p.storyboard_method==='source_units'};if(kind==='continuity_confirm'){setProject(await api(`/projects/${p.id}/shots/${target}/continuity/accept`,{revision:p.revision,...opts}));notify('已记录人工衔接复核，原有媒体与种子保留');return;}if(kind==='storyboard_confirm'){setProject(await api(`/projects/${p.id}/storyboard/outline/confirm`,outlineReview));notify('分镜汇总已确认，可逐镜生成');return;}if(kind==='storyboard'&&opts.confirm_outline){p=await api(`/projects/${p.id}/storyboard/outline/confirm`,outlineReview);setProject(p);delete opts.confirm_outline;}const submitted=await api(`/projects/${p.id}/jobs/${kind}`,{revision:p.revision,target,options:opts});if(['script_assets','storyboard','storyboard_outline','storyboard_timing'].includes(kind))setProject(await api('/projects/'+p.id));setTasks(await api('/tasks'));notify(submitted.phase==='ai_prepare'?'AI 准备将自动并发执行，完成后进入 ComfyUI 队列':submitted.queue_group==='comfy'?'已加入 ComfyUI 队列，可同时继续 AI 创作':submitted.queue_group==='local'?'已加入本地导出队列':'已加入 AI 任务队列');});
