 const projectCommand=(mode:string)=>guard(async()=>{const action=projectAction!;const p=await api('/projects/'+action.project.id);if(p.name!==action.project.name){setProjectAction({...action,project:p});throw new Error('项目名称已更新，请核对后重试');}if(mode==='backup'){const task=await api(`/projects/${p.id}/jobs/export`,{revision:p.revision,options:{format:'zip'}});setProjectAction({...action,project:p,mode:'backup',task_id:task.id});setTasks(await api('/tasks'));return;}if(mode==='rename'){const updated=await api(`/projects/${p.id}/rename`,{revision:p.revision,name:action.name});if(project?.id===p.id){setProject(updated);setDirty(false);}}if(mode==='copy'){const copied=await api(`/projects/${p.id}/copy`,{...p,copy_name:action.name});setProject(copied);setDirty(false);setTab('brief');setCaptionJSON('');}if(mode==='delete'){await api(`/projects/${p.id}/delete`,{revision:p.revision});if(project?.id===p.id){setProject(null);setDirty(false);}}setProjectAction(null);await refresh();notify(mode==='delete'?'项目已移入回收站':mode==='copy'?'已创建独立项目副本':'项目已重命名');});
 const createAutomatic=()=>guard(async()=>{const p=await api('/projects',creation);setProject(p);setDirty(false);setTab('brief');await refresh();await api(`/projects/${p.id}/auto-creation/start`,{revision:p.revision});applyTaskProject(await api('/projects/'+p.id));notify('自动创作已启动，可关闭页面，后台会继续保存进度');});
 const create=(file?:File)=>guard(async()=>{
 const isVideo=!!file?.type.startsWith('video/');
 let p=await api('/projects',{...creation,name:creation.name||file?.name.replace(/\.[^.]+$/,'')||'',story:creation.story.trim()||(creation.project_type==='medical'?'待导入医学指南':isVideo?'参考视频：'+file!.name+'。请结合导入的素材规划创作。':'')});
 setProject(p);setDirty(false);setTab('brief');
 if(file&&creation.project_type==='medical'&&file.name.toLowerCase().endsWith('.pdf')){const body=new FormData();body.set('file',file);body.set('revision',String(p.revision));p=(await api(`/projects/${p.id}/medical-director/sources/upload`,body)).project;setProject(p)}
 if(file&&isVideo){const body=new FormData();body.set('file',file);const material=await api('/upload',body);p=await api('/projects/'+p.id,{...p,media:[...p.media,material]},'PUT');setProject(p);setTab('assets')}
 await refresh();notify(isVideo?'参考视频已导入，可在素材区继续创作':'项目已创建，原始内容保持不变');
 });
 const uploadFiles=async(files:FileList|null,assetId?:string)=>{if(!files)return;await guard(async()=>{const uploaded:Obj[]=[];for(const file of Array.from(files)){const body=new FormData();body.append('file',file);uploaded.push(await api('/upload',body));}edit(p=>{for(const m of uploaded){p.media.push(m);if(assetId&&m.kind==='image'){const a=p.assets.find(a=>a.id===assetId)!;a.references.push({id:newId(),media:m.media,role:a.kind==='character'?'identity':a.kind==='scene'?'environment':'prop',note:'',path:''});}}});});};
 const addAsset=(kind:string)=>edit(p=>p.assets.push({id:newId(),kind,name:'新'+kindName[kind],is_protagonist:kind==='character'&&!p.assets.some(a=>a.kind==='character'),description:'',model:'qwen-image-2.1',model_source:'default',prompt:'',references:[],previews:[],adopted:null}));
 const editAsset=(id:string,fn:(a:Obj)=>void)=>edit(p=>{const a=p.assets.find(a=>a.id===id)!;const oldName=a.name;fn(a);if(a.name!==oldName){for(const group of Object.values(a.visual_profile?.groups||{}) as Obj[])for(const item of Object.values(group.fields||{}) as Obj[])item.owner=a.name;for(const item of Object.values(a.visual_profile?.fields||{}) as Obj[])item.owner=a.name;a.prompt='';a.prompt_zh='';a.previews.forEach((m:Obj)=>m.stale=true);}});
 const activeShot=project?.shots.find(s=>s.id===viewShot),activeFrameShot=project?.shots.find(s=>s.id===viewFrameShot),activeVideoShot=project&&viewVideoShot?h3VideoShot(project,viewVideoShot):undefined;
