 const adoptTiming=()=>guard(async()=>{const p=await save();const s=p.shots.find(s=>s.id===viewShot);if(!s?.timing_suggestion)throw new Error('请先重新审查本镜时序');const updated=await api(`/projects/${p.id}/shots/${s.id}/timing/accept`,{revision:p.revision,suggestion_id:s.timing_suggestion.id});setProject(updated);setDirty(false);await refresh();notify(`已采用建议时长：${s.timing_suggestion.before_seconds} → ${s.timing_suggestion.recommended_seconds} 秒；动作段与提示词已同步。`);});
 const shotReferencePicker=activeShot&&<ShotReferenceButton key={activeShot.id} selectedIds={activeShot.shot_reference_ids||[]} onSelect={ids=>edit(p=>{const shot=p.shots.find(s=>s.id===activeShot.id);if(shot)shot.shot_reference_ids=ids})}/>;
 const editShotById=(id:string,fn:(s:Obj)=>void)=>edit(p=>{const shot=p.shots.find(s=>s.id===id);if(!shot)return;const before=JSON.stringify([shot.description,shot.duration,shot.prompt,shot.native,shot.actions]);fn(shot);if(before!==JSON.stringify([shot.description,shot.duration,shot.prompt,shot.native,shot.actions])){shot.natural_status='unverified';if(shot.timing_suggestion)shot.timing_suggestion.status='stale';}p.confirmed=false;});
